import unittest

from hourglass.parsing import parse_span
from hourglass.gaps import find_gaps

OPEN = parse_span("09:00-17:00")


def gaps_for(*texts):
    return find_gaps([parse_span(text) for text in texts], OPEN)


class FindGapsTests(unittest.TestCase):
    def test_gap_in_the_middle(self):
        self.assertEqual(
            gaps_for("09:00-12:00", "13:00-17:00"),
            ["gap 12:00-13:00 (60 min)"]
        )

    def test_edges_and_overlaps(self):
        self.assertEqual(
            gaps_for("10:00-12:00", "11:00-16:00"),
            [
                "gap 09:00-10:00 (60 min)",
                "gap 16:00-17:00 (60 min)"
            ]
        )

    def test_full_coverage_has_no_gaps(self):
        self.assertEqual(gaps_for("09:00-17:00"), [])

    def test_nobody_working(self):
        self.assertEqual(
            gaps_for(), ["gap 09:00-17:00 (480 min)"]
        )

    def test_outside_hours_raises(self):
        with self.assertRaises(ValueError):
            gaps_for("08:00-10:00")
